/**
 * IBGESF Valuation Extractor – Worker v4
 * v4 (set/2026): novo endpoint POST /extract-planilha — extrai DRE (3 anos), Balanço
 *   (4 datas), DFC, normalização e qualidade em R$ mil para preencher a planilha
 *   Valuation_BuyThenBuild. Body: { arquivos:[{base64,mime_type,nome}], textos:[{nome,texto}],
 *   texto_livre:"...", ano_referencia:2025 }. Modelo: env.EXTRACT_MODEL (padrão claude-sonnet-5,
 *   com fallback para claude-haiku-4-5-20251001). /extract (v3) continua disponível.
 *
 * Arquitetura: recebe PDF(s)/DOCX como base64 → Claude lê nativamente
 * Múltiplos PDFs: consolida resultados (usa o de maior confiança por indicador)
 * Para textos estruturados (XLSX exportado como CSV) → recebe como texto
 *
 * Endpoint: POST /extract
 * Headers: X-Api-Key: ibgesf2024secure
 * Body (PDF único):   { tipo:"pdf", arquivo_base64:"...", mime_type:"application/pdf", nome:"arquivo.pdf" }
 * Body (múltiplos):   { tipo:"pdf", arquivos:[{base64:"...", mime_type:"...", nome:"..."}, ...] }
 * Body (texto):       { tipo:"texto", texto:"...", nome:"arquivo.xlsx" }
 *
 * Response: { ok:true, indicadores:{...}, modelo:"...", modo:"pdf-nativo"|"texto", arquivos_processados:N }
 */

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST,OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type,X-Api-Key,X-API-Key",
};


// ═══════════════════════════════════════════════════════════════════════════
// PLANILHA ENGINE + TEMPLATE (embedded) — motor de cálculo do valuation
// Engine: avalia fórmulas XLSX | Template: planilha Valuation_BuyThenBuild
// ═══════════════════════════════════════════════════════════════════════════
let _PlanilhaEngine_;
/* ═══════════════════════════════════════════════════════════════════════════
   PLANILHA ENGINE — avalia as fórmulas da planilha Valuation_BuyThenBuild
   diretamente a partir do XML do .xlsx (a planilha É o motor de cálculo).
   Suporta: + − * / ^ & = <> < > <= >=, IF, MIN, MAX, SUM, SUMPRODUCT,
   AVERAGE, COUNTIF, intervalos, referências entre abas e operações em array.
   Funciona no navegador e no Node (sem dependências).
   ═══════════════════════════════════════════════════════════════════════════ */
(function (root) {
  'use strict';

  const ERR = (code) => ({ err: code });
  const isErr = (v) => v && typeof v === 'object' && 'err' in v;

  // ── XML helpers ────────────────────────────────────────────────────────────
  function decodeXml(s) {
    return String(s)
      .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'").replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
      .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
      .replace(/&amp;/g, '&');
  }
  function encodeXml(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function parseSharedStrings(xml) {
    const out = [];
    const siRx = /<si>([\s\S]*?)<\/si>/g;
    let m;
    while ((m = siRx.exec(xml)) !== null) {
      const parts = [];
      const tRx = /<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g;
      let t;
      while ((t = tRx.exec(m[1])) !== null) parts.push(decodeXml(t[1]));
      out.push(parts.join(''));
    }
    return out;
  }

  function parseSheet(xml, sst) {
    const cells = {};
    const cRx = /<c r="([A-Z]+\d+)"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g;
    let m;
    while ((m = cRx.exec(xml)) !== null) {
      const ref = m[1], attrs = m[2] || '', inner = m[3] || '';
      const t = (attrs.match(/\bt="([^"]+)"/) || [])[1] || 'n';
      const fM = inner.match(/<f[^>]*>([\s\S]*?)<\/f>/);
      const vM = inner.match(/<v>([\s\S]*?)<\/v>/);
      const isM = inner.match(/<is>([\s\S]*?)<\/is>/);
      const cell = {};
      if (fM) cell.f = decodeXml(fM[1]);
      if (t === 's' && vM) cell.v = sst[+vM[1]];
      else if (t === 'inlineStr' && isM) cell.v = decodeXml((isM[1].match(/<t[^>]*>([\s\S]*?)<\/t>/) || [])[1] || '');
      else if (t === 'str' && vM) cell.v = decodeXml(vM[1]);
      else if (t === 'b' && vM) cell.v = vM[1] === '1';
      else if (vM) cell.v = parseFloat(vM[1]);
      else cell.v = null;
      cells[ref] = cell;
    }
    return cells;
  }

  // ── Referências ────────────────────────────────────────────────────────────
  function colToNum(c) { let n = 0; for (const ch of c) n = n * 26 + (ch.charCodeAt(0) - 64); return n; }
  function numToCol(n) { let s = ''; while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; }
  function splitRef(ref) { const m = ref.replace(/\$/g, '').match(/^([A-Z]+)(\d+)$/); return { col: colToNum(m[1]), row: +m[2] }; }

  // ── Tokenizer ──────────────────────────────────────────────────────────────
  function tokenize(src) {
    const toks = [];
    let i = 0;
    const refPart = '\\$?[A-Z]{1,3}\\$?\\d+';
    const refRx = new RegExp('^(?:([A-Za-z0-9_]+)!)?(' + refPart + ')(?::(' + refPart + '))?');
    while (i < src.length) {
      const ch = src[i];
      if (ch === ' ') { i++; continue; }
      if (ch === '"') {
        let j = i + 1, s = '';
        while (j < src.length) {
          if (src[j] === '"' && src[j + 1] === '"') { s += '"'; j += 2; continue; }
          if (src[j] === '"') break;
          s += src[j++];
        }
        toks.push({ t: 'str', v: s }); i = j + 1; continue;
      }
      const rest = src.slice(i);
      // referência (com ou sem aba) — testar antes de número, pois "1_DRE!D8" começa com dígito
      const rm = rest.match(refRx);
      if (rm && (rm[1] || /^[$A-Z]/.test(rest))) {
        toks.push({ t: 'ref', sheet: rm[1] || null, a: rm[2].replace(/\$/g, ''), b: rm[3] ? rm[3].replace(/\$/g, '') : null });
        i += rm[0].length; continue;
      }
      const nm = rest.match(/^\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/);
      if (nm) { toks.push({ t: 'num', v: parseFloat(nm[0]) }); i += nm[0].length; continue; }
      const fm = rest.match(/^([A-Z][A-Z0-9.]*)\(/);
      if (fm) { toks.push({ t: 'fn', v: fm[1] }); i += fm[1].length + 1; continue; }
      const op2 = rest.slice(0, 2);
      if (op2 === '<=' || op2 === '>=' || op2 === '<>') { toks.push({ t: 'op', v: op2 }); i += 2; continue; }
      if ('+-*/^&=<>%'.includes(ch)) { toks.push({ t: 'op', v: ch }); i++; continue; }
      if (ch === '(') { toks.push({ t: '(' }); i++; continue; }
      if (ch === ')') { toks.push({ t: ')' }); i++; continue; }
      if (ch === ',' || ch === ';') { toks.push({ t: ',' }); i++; continue; }
      if (/^TRUE|^FALSE/.test(rest)) { const b = rest.startsWith('TRUE'); toks.push({ t: 'bool', v: b }); i += b ? 4 : 5; continue; }
      throw new Error('Token inválido em "' + src + '" posição ' + i);
    }
    return toks;
  }

  // ── Parser (Pratt) ─────────────────────────────────────────────────────────
  const BIN = { '=': 1, '<>': 1, '<': 1, '>': 1, '<=': 1, '>=': 1, '&': 2, '+': 3, '-': 3, '*': 4, '/': 4, '^': 5 };
  function parse(src) {
    const toks = tokenize(src);
    let p = 0;
    const peek = () => toks[p];
    const next = () => toks[p++];
    function primary() {
      const tk = next();
      if (!tk) throw new Error('Fim inesperado: ' + src);
      if (tk.t === 'num') return { k: 'num', v: tk.v };
      if (tk.t === 'str') return { k: 'str', v: tk.v };
      if (tk.t === 'bool') return { k: 'bool', v: tk.v };
      if (tk.t === 'ref') return { k: 'ref', sheet: tk.sheet, a: tk.a, b: tk.b };
      if (tk.t === 'op' && tk.v === '-') return { k: 'neg', e: unaryOperand() };
      if (tk.t === 'op' && tk.v === '+') return unaryOperand();
      if (tk.t === '(') { const e = expr(0); if (next().t !== ')') throw new Error('Esperado )'); return e; }
      if (tk.t === 'fn') {
        const args = [];
        if (peek() && peek().t === ')') { next(); return { k: 'fn', n: tk.v, args }; }
        for (;;) {
          args.push(expr(0));
          const s = next();
          if (s.t === ')') break;
          if (s.t !== ',') throw new Error('Esperado , ou ) em ' + src);
        }
        return { k: 'fn', n: tk.v, args };
      }
      throw new Error('Token inesperado ' + JSON.stringify(tk) + ' em ' + src);
    }
    // No Excel, o menos unário tem precedência maior que ^
    function unaryOperand() { return postfix(primary()); }
    function postfix(e) {
      while (peek() && peek().t === 'op' && peek().v === '%') { next(); e = { k: 'pct', e }; }
      return e;
    }
    function expr(minPrec) {
      let left = postfix(primary());
      for (;;) {
        const tk = peek();
        if (!tk || tk.t !== 'op' || !(tk.v in BIN)) break;
        const prec = BIN[tk.v];
        if (prec < minPrec) break;
        next();
        const right = expr(tk.v === '^' ? prec + 1 : prec + 1);
        left = { k: 'bin', op: tk.v, l: left, r: right };
      }
      return left;
    }
    const ast = expr(0);
    if (p < toks.length) throw new Error('Sobrou token em ' + src);
    return ast;
  }

  // ── Workbook ───────────────────────────────────────────────────────────────
  class Workbook {
    constructor(files) {
      // files: { path: xmlString } do zip
      this.files = files;
      this.sst = files['xl/sharedStrings.xml'] ? parseSharedStrings(files['xl/sharedStrings.xml']) : [];
      const wbXml = files['xl/workbook.xml'];
      const rels = files['xl/_rels/workbook.xml.rels'];
      const relMap = {};
      rels.replace(/<Relationship [^>]*?Id="([^"]+)"[^>]*?Target="([^"]+)"[^>]*?\/>/g, (_, id, tgt) => { relMap[id] = tgt; });
      rels.replace(/<Relationship [^>]*?Target="([^"]+)"[^>]*?Id="([^"]+)"[^>]*?\/>/g, (_, tgt, id) => { relMap[id] = relMap[id] || tgt; });
      this.sheets = {};
      this.order = [];
      wbXml.replace(/<sheet [^>]*?name="([^"]+)"[^>]*?r:id="([^"]+)"[^>]*?\/>/g, (_, name, rid) => {
        const n = decodeXml(name);
        const path = 'xl/' + relMap[rid].replace(/^\/?xl\//, '');
        this.sheets[n] = { name: n, path, cells: parseSheet(files[path], this.sst) };
        this.order.push(n);
      });
      this.ast = {};
      this.cache = {};
      this.dirtyInputs = {}; // sheet -> {ref: true}
      this.textOverrides = {}; // sheet -> {ref:true}
    }

    cell(sheet, ref) { const s = this.sheets[sheet]; return s ? s.cells[ref] : undefined; }

    // Define valor de entrada (número ou texto)
    set(sheet, ref, value) {
      const s = this.sheets[sheet];
      if (!s) throw new Error('Aba inexistente: ' + sheet);
      const c = s.cells[ref] || (s.cells[ref] = {});
      if (c.f) throw new Error('Tentativa de sobrescrever fórmula em ' + sheet + '!' + ref);
      c.v = value;
      (this.dirtyInputs[sheet] = this.dirtyInputs[sheet] || {})[ref] = true;
      this.cache = {};
    }
    get(sheet, ref) {
      const v = this.value(sheet, ref);
      return v;
    }
    num(sheet, ref) { const v = this.value(sheet, ref); return (typeof v === 'number' && isFinite(v)) ? v : (v === true ? 1 : 0); }

    value(sheet, ref) {
      const key = sheet + '!' + ref;
      if (key in this.cache) {
        if (this.cache[key] === CYCLE) throw new Error('Referência circular em ' + key);
        return this.cache[key];
      }
      const c = this.cell(sheet, ref);
      if (!c) return null;
      if (!c.f) return c.v == null ? null : c.v;
      this.cache[key] = CYCLE;
      let ast = this.ast[key];
      if (!ast) ast = this.ast[key] = parse(c.f);
      let v = this.evalNode(ast, sheet);
      if (v && v.arr) v = v.arr[0];
      this.cache[key] = v;
      return v;
    }

    rangeVals(sheet, a, b) {
      const A = splitRef(a), B = splitRef(b);
      const out = [];
      for (let r = Math.min(A.row, B.row); r <= Math.max(A.row, B.row); r++)
        for (let c = Math.min(A.col, B.col); c <= Math.max(A.col, B.col); c++)
          out.push(this.value(sheet, numToCol(c) + r));
      return out;
    }

    evalNode(n, sheet) {
      switch (n.k) {
        case 'num': case 'str': case 'bool': return n.v;
        case 'ref': {
          const sh = n.sheet || sheet;
          if (!this.sheets[sh]) return ERR('#REF!');
          if (n.b) return { arr: this.rangeVals(sh, n.a, n.b), range: true };
          return this.value(sh, n.a);
        }
        case 'neg': return mapUnary(this.evalNode(n.e, sheet), x => -toNum(x));
        case 'pct': return mapUnary(this.evalNode(n.e, sheet), x => toNum(x) / 100);
        case 'bin': return binop(n.op, this.evalNode(n.l, sheet), this.evalNode(n.r, sheet));
        case 'fn': return this.callFn(n, sheet);
      }
      throw new Error('Nó desconhecido');
    }

    callFn(n, sheet) {
      const ev = (i) => this.evalNode(n.args[i], sheet);
      const flat = (vals) => {
        const out = [];
        for (const v of vals) { if (v && v.arr) out.push(...v.arr.map(x => ({ x, fromRange: !!v.range }))); else out.push({ x: v, fromRange: false }); }
        return out;
      };
      switch (n.n) {
        case 'IF': {
          const c = ev(0);
          if (isErr(c)) return c;
          const truthy = typeof c === 'string' ? c.length > 0 : !!toNum(c);
          if (truthy) return ev(1);
          return n.args.length > 2 ? ev(2) : false;
        }
        case 'SUM': {
          let s = 0;
          for (const { x, fromRange } of flat(n.args.map((_, i) => ev(i)))) {
            if (isErr(x)) return x;
            if (typeof x === 'number') s += x; else if (!fromRange && x != null) s += toNum(x);
          }
          return s;
        }
        case 'MIN': case 'MAX': {
          const nums = [];
          for (const { x, fromRange } of flat(n.args.map((_, i) => ev(i)))) {
            if (isErr(x)) return x;
            if (typeof x === 'number') nums.push(x); else if (!fromRange && x != null) nums.push(toNum(x));
          }
          if (!nums.length) return 0;
          return n.n === 'MIN' ? Math.min(...nums) : Math.max(...nums);
        }
        case 'AVERAGE': {
          const nums = [];
          for (const { x, fromRange } of flat(n.args.map((_, i) => ev(i)))) {
            if (isErr(x)) return x;
            if (typeof x === 'number') nums.push(x); else if (!fromRange && x != null) nums.push(toNum(x));
          }
          if (!nums.length) return ERR('#DIV/0!');
          return nums.reduce((a, b) => a + b, 0) / nums.length;
        }
        case 'COUNTIF': {
          const r = ev(0); const crit = ev(1);
          const arr = r && r.arr ? r.arr : [r];
          let cnt = 0;
          for (const x of arr) {
            if (typeof crit === 'number') { if (typeof x === 'number' && x === crit) cnt++; }
            else if (typeof crit === 'string') {
              const m = crit.match(/^(<=|>=|<>|<|>|=)?(.*)$/);
              const op = m[1] || '=', val = isNaN(parseFloat(m[2])) ? m[2] : parseFloat(m[2]);
              if (x == null) continue;
              if (cmp(op, x, val)) cnt++;
            }
          }
          return cnt;
        }
        case 'COUNT': {
          let cnt = 0;
          for (const { x } of flat(n.args.map((_, i) => ev(i)))) if (typeof x === 'number') cnt++;
          return cnt;
        }
        case 'OR': case 'AND': {
          const vals = flat(n.args.map((_, i) => ev(i))).map(o => o.x);
          for (const x of vals) if (isErr(x)) return x;
          const bools = vals.filter(x => x != null && typeof x !== 'string').map(x => !!toNum(x));
          return n.n === 'OR' ? bools.some(Boolean) : (bools.length > 0 && bools.every(Boolean));
        }
        case 'IFERROR': {
          const v = ev(0);
          return isErr(v) ? ev(1) : v;
        }
        case 'SUMPRODUCT': {
          const arrs = n.args.map((_, i) => { const v = ev(i); return v && v.arr ? v.arr : [v]; });
          const len = Math.max(...arrs.map(a => a.length));
          let s = 0;
          for (let i = 0; i < len; i++) {
            let prod = 1;
            for (const a of arrs) {
              const x = a.length === 1 ? a[0] : a[i];
              if (isErr(x)) return x;
              prod *= (typeof x === 'number') ? x : (x === true ? 1 : 0);
            }
            s += prod;
          }
          return s;
        }
      }
      throw new Error('Função não suportada: ' + n.n);
    }

    // Avalia todas as fórmulas e devolve número de erros
    recalc() {
      this.cache = {};
      const errors = [];
      for (const sh of this.order) {
        const cells = this.sheets[sh].cells;
        for (const ref in cells) {
          if (!cells[ref].f) continue;
          try {
            const v = this.value(sh, ref);
            if (isErr(v)) errors.push(sh + '!' + ref + ' ' + v.err);
          } catch (e) { errors.push(sh + '!' + ref + ' ' + e.message); }
        }
      }
      return errors;
    }

    // Marca uma célula de texto para ser regravada (ex.: cabeçalhos de ano)
    setText(sheet, ref, text) {
      const c = this.cell(sheet, ref) || (this.sheets[sheet].cells[ref] = {});
      c.v = text; delete c.f;
      (this.textOverrides[sheet] = this.textOverrides[sheet] || {})[ref] = true;
      this.cache = {};
    }

    // Gera os XMLs atualizados: valores de entrada + valores calculados das fórmulas (cache)
    serialize() {
      const out = {};
      for (const sh of this.order) {
        const s = this.sheets[sh];
        let xml = this.files[s.path];
        const dirty = this.dirtyInputs[sh] || {};
        const texts = this.textOverrides[sh] || {};
        xml = xml.replace(/<c r="([A-Z]+\d+)"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g, (whole, ref, attrs) => {
          const c = s.cells[ref];
          if (!c) return whole;
          const style = (attrs.match(/\bs="(\d+)"/) || [])[1];
          const sAttr = style ? ` s="${style}"` : '';
          if (texts[ref]) return `<c r="${ref}"${sAttr} t="inlineStr"><is><t xml:space="preserve">${encodeXml(c.v)}</t></is></c>`;
          if (c.f) {
            let v;
            try { v = this.value(sh, ref); } catch (e) { v = ERR('#VALUE!'); }
            const f = `<f aca="false">${encodeXml(c.f)}</f>`;
            if (isErr(v)) return `<c r="${ref}"${sAttr} t="e">${f}<v>${v.err}</v></c>`;
            if (typeof v === 'string') return `<c r="${ref}"${sAttr} t="str">${f}<v>${encodeXml(v)}</v></c>`;
            if (typeof v === 'boolean') return `<c r="${ref}"${sAttr} t="b">${f}<v>${v ? 1 : 0}</v></c>`;
            return `<c r="${ref}"${sAttr} t="n">${f}<v>${fmtNum(v)}</v></c>`;
          }
          if (dirty[ref]) {
            if (c.v == null || c.v === '') return `<c r="${ref}"${sAttr}/>`;
            if (typeof c.v === 'string') return `<c r="${ref}"${sAttr} t="inlineStr"><is><t xml:space="preserve">${encodeXml(c.v)}</t></is></c>`;
            return `<c r="${ref}"${sAttr} t="n"><v>${fmtNum(c.v)}</v></c>`;
          }
          return whole;
        });
        out[s.path] = xml;
      }
      // Força recálculo completo ao abrir no Excel/LibreOffice
      out['xl/workbook.xml'] = this.files['xl/workbook.xml'].replace(/<calcPr([^/]*)\/>/, (m, a) => /fullCalcOnLoad/.test(a) ? m : `<calcPr${a} fullCalcOnLoad="1"/>`);
      return out;
    }
  }
  const CYCLE = { cycle: true };

  function fmtNum(v) {
    if (typeof v !== 'number' || !isFinite(v)) return '0';
    return String(Math.round(v * 1e10) / 1e10);
  }
  function toNum(x) {
    if (typeof x === 'number') return x;
    if (x === true) return 1;
    if (x === false || x == null || x === '') return 0;
    const n = parseFloat(x);
    return isNaN(n) ? 0 : n;
  }
  function mapUnary(v, f) {
    if (isErr(v)) return v;
    if (v && v.arr) return { arr: v.arr.map(x => isErr(x) ? x : f(x)) };
    return f(v);
  }
  function cmp(op, a, b) {
    if (a == null) a = typeof b === 'string' ? '' : 0;
    if (b == null) b = typeof a === 'string' ? '' : 0;
    if (typeof a === 'string' && typeof b === 'string') { a = a.toLowerCase(); b = b.toLowerCase(); }
    else if (typeof a === 'string' || typeof b === 'string') {
      // no Excel, texto > número
      const ta = typeof a === 'string' ? 1 : 0, tb = typeof b === 'string' ? 1 : 0;
      a = ta; b = tb;
    } else { a = toNum(a); b = toNum(b); }
    switch (op) {
      case '=': return a === b; case '<>': return a !== b;
      case '<': return a < b; case '>': return a > b;
      case '<=': return a <= b; case '>=': return a >= b;
    }
    return false;
  }
  function scalarBin(op, a, b) {
    if (isErr(a)) return a; if (isErr(b)) return b;
    switch (op) {
      case '+': return toNum(a) + toNum(b);
      case '-': return toNum(a) - toNum(b);
      case '*': return toNum(a) * toNum(b);
      case '/': { const d = toNum(b); return d === 0 ? ERR('#DIV/0!') : toNum(a) / d; }
      case '^': { const r = Math.pow(toNum(a), toNum(b)); return isFinite(r) ? r : ERR('#NUM!'); }
      case '&': return String(a == null ? '' : a) + String(b == null ? '' : b);
      default: return cmp(op, a, b);
    }
  }
  function binop(op, a, b) {
    const A = a && a.arr, B = b && b.arr;
    if (!A && !B) return scalarBin(op, a, b);
    const la = A ? A.length : 1, lb = B ? B.length : 1, n = Math.max(la, lb);
    const out = [];
    for (let i = 0; i < n; i++) out.push(scalarBin(op, A ? (la === 1 ? A[0] : A[i]) : a, B ? (lb === 1 ? B[0] : B[i]) : b));
    return { arr: out };
  }

  const api = { Workbook, parse, tokenize, parseSheet, parseSharedStrings, decodeXml, encodeXml };
  _PlanilhaEngine_=api;
})({})

const PlanilhaEngine=_PlanilhaEngine_;

